<body>
    <div class="todo-container">
        <h1>Todo</h1>

        <div class="input-group">
            <input type="text" id="todo-input" placeholder="Add a new todo..." autocomplete="off">
            <button class="add-btn" id="add-btn">Add</button>
        </div>

        <div class="filters">
            <button class="filter-btn active" data-filter="all">All</button>
            <button class="filter-btn" data-filter="active">Active</button>
            <button class="filter-btn" data-filter="completed">Completed</button>
        </div>

        <ul class="todo-list" id="todo-list"></ul>

        <div class="stats" id="stats"></div>
    </div>

    <script>
        const STORAGE_KEY = 'todo-app-data';
        let todos = [];
        let currentFilter = 'all';

        function loadTodos() {
            try {
                const stored = localStorage.getItem(STORAGE_KEY);
                todos = stored ? JSON.parse(stored) : [];
            } catch (e) {
                console.error('Failed to load todos:', e);
                todos = [];
            }
            render();
        }

        function saveTodos() {
            try {
                localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
            } catch (e) {
                console.error('Failed to save todos:', e);
            }
        }

        function addTodo(text) {
            const trimmed = text.trim();
            if (!trimmed) return;

            todos.unshift({
                id: Date.now(),
                text: trimmed,
                completed: false
            });
            saveTodos();
            render();
        }

        function toggleTodo(id) {
            todos = todos.map(todo => 
                todo.id === id ? { ...todo, completed: !todo.completed } : todo
            );
            saveTodos();
            render();
        }

        function deleteTodo(id) {
            todos = todos.filter(todo => todo.id !== id);
            saveTodos();
            render();
        }

        function getFilteredTodos() {
            switch (currentFilter) {
                case 'active':
                    return todos.filter(todo => !todo.completed);
                case 'completed':
                    return todos.filter(todo => todo.completed);
                default:
                    return todos;
            }
        }

        function render() {
            const listEl = document.getElementById('todo-list');
            const statsEl = document.getElementById('stats');
            const filtered = getFilteredTodos();

            if (filtered.length === 0) {
                listEl.innerHTML = '<li class="empty-state">No todos yet. Add one above!</li>';
                statsEl.textContent = '';
                return;
            }

            listEl.innerHTML = filtered.map(todo => `
                <li class="todo-item ${todo.completed ? 'completed' : ''}"
                    data-id="${todo.id}">
                    <input type="checkbox" class="todo-checkbox" 
                        ${todo.completed ? 'checked' : ''}
                        onchange="toggleTodo(${todo.id})">
                    <span class="todo-text">${escapeHtml(todo.text)}</span>
                    <button class="delete-btn" onclick="deleteTodo(${todo.id})">&times;</button>
                </li>
            `).join('');

            const activeCount = todos.filter(t => !t.completed).length;
            statsEl.textContent = `${activeCount} item${activeCount !== 1 ? 's' : ''} remaining`;
        }

        function escapeHtml(text) {
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }

        // Event listeners
        document.getElementById('todo-input').addEventListener('keypress', (e) => {
            if (e.key === 'Enter') {
                addTodo(e.target.value);
                e.target.value = '';
            }
        });

        document.getElementById('add-btn').addEventListener('click', () => {
            const input = document.getElementById('todo-input');
            addTodo(input.value);
            input.value = '';
            input.focus();
        });

        document.querySelectorAll('.filter-btn').forEach(btn => {
            btn.addEventListener('click', () => {
                document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
                btn.classList.add('active');
                currentFilter = btn.dataset.filter;
                render();
            });
        });

        // Initialize
        loadTodos();
    </script>
</body>
